from typing import List, Tuple, Optional

def perceive(observation_history: list[str]) -> str:
    """
    Parse the raw observation text and produce a concise summary of decision-relevant features.
    The output must:
    - Be <2000 characters
    - Never be empty
    - Never raise exceptions
    - Capture enough state that the action between two consecutive states is recoverable
    """
    try:
        obs = observation_history[-1] if observation_history else ""
        if not obs:
            return "[]"

        # Detect which encoding is present
        grid = None

        # Try to detect JSON array encoding (Autumn string grid)
        json_start = obs.find("[[")
        if json_start != -1:
            json_end = obs.rfind("]]")
            if json_end != -1:
                try:
                    json_str = obs[json_start:json_end+2]
                    grid = json.loads(json_str)
                except (json.JSONDecodeError, ValueError):
                    pass

        # If JSON parsing failed or not found, try integer grid encoding
        if grid is None:
            grid_lines = []
            lines = obs.split('\n')
            in_grid = False
            for line in lines:
                line_stripped = line.strip()
                if line_stripped.startswith('<grid_'):
                    in_grid = True
                    continue
                if in_grid:
                    # Try to parse as a bracketed list of integers
                    if line_stripped.startswith('[') and line_stripped.endswith(']'):
                        try:
                            # Extract integers from the line
                            nums_str = line_stripped.strip('[]').split(',')
                            row = [int(x.strip()) for x in nums_str]
                            if grid is None:
                                grid = []
                            grid.append(row)
                        except (ValueError, IndexError):
                            continue
                    elif line_stripped.startswith('['):
                        # Could be a partial line, try parsing what we can
                        try:
                            nums_str = line_stripped.strip('[]').split(',')
                            row = [int(x.strip()) for x in nums_str if x.strip()]
                            if row:
                                if grid is None:
                                    grid = []
                                grid.append(row)
                        except ValueError:
                            continue

        if grid is None or len(grid) == 0:
            return "[]"

        # Determine grid dimensions
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 and isinstance(grid[0], list) else 0

        if rows == 0 or cols == 0:
            return "[]"

        # Find the agent position (the moving cursor/player)
        # In these grid environments, the agent is typically at a specific position
        # that changes with movement commands
        agent_pos = None
        non_black_cells = []

        # Convert colour names to integers if needed
        colour_map = {
            "black": 0, "blue": 1, "red": 2, "green": 3, "yellow": 4,
            "gray": 5, "gold": 5, "magenta": 6, "orange": 7, "lightblue": 8,
            "maroon": 9, "white": 10, "darkgray": 11, "darkgreen": 3,
            "light-gray": 5, "dark-red": 9, "light-blue": 8, "dark-gray": 11
        }

        # Parse grid cells
        for r in range(rows):
            for c in range(cols):
                cell = grid[r][c]
                # Convert cell to integer if it's a string colour name
                if isinstance(cell, str):
                    cell_val = colour_map.get(cell.lower(), 5)  # default to gray
                else:
                    cell_val = int(cell)

                # Non-black cells are interesting
                if cell_val != 0 and cell_val != 5:  # Not black and not gray (background)
                    non_black_cells.append((r, c, cell_val))

        # Build feature string
        features = []

        # Report non-background cells (things placed by clicks or special objects)
        for r, c, val in sorted(non_black_cells):
            features.append(f"({r} {c} {val})")

        # If no non-background cells, report the most prominent non-gray cells
        if not features:
            # Look for lightblue (8) cells which seem to be targets
            for r in range(rows):
                for c in range(cols):
                    cell = grid[r][c]
                    if isinstance(cell, str):
                        cell_val = colour_map.get(cell.lower(), 5)
                    else:
                        cell_val = int(cell)
                    if cell_val == 8:  # lightblue - target indicators
                        features.append(f"({r} {c} 8)")

            # If still nothing interesting, report gray cells (background) positions
            if not features:
                # Report border/edge cells to give some spatial information
                for r in range(min(3, rows)):
                    for c in range(min(3, cols)):
                        cell = grid[r][c]
                        if isinstance(cell, str):
                            cell_val = colour_map.get(cell.lower(), 5)
                        else:
                            cell_val = int(cell)
                        if cell_val != 0:  # not black
                            features.append(f"({r} {c} {cell_val})")

        result = "[" + ", ".join(features) + "]" if features else "[]"
        return result[:2000]  # Ensure under 2000 chars

    except Exception:
        # Never raise, return a minimal representation
        return "[]"

