import json
from collections import Counter, defaultdict

def perceive(observation_history: list[str]) -> str:
    """
    Extract decision‑relevant features from the last observation.
    Output is a concise (<2000 char) text summary that changes when the world changes,
    enabling recovery of the action between two consecutive states.
    Never raises an exception and never returns an empty string.
    """
    try:
        obs = observation_history[-1]
        grid = _parse_grid(obs)
        if grid is None or len(grid) == 0:
            return "Grid error. Empty state."

        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0

        # Determine background colours (most frequent and >10%)
        all_colours = [cell for row in grid for cell in row]
        if not all_colours:
            return f"Grid {rows}x{cols}. No cells."

        freq = Counter(all_colours)
        total = len(all_colours)
        sorted_colours = freq.most_common()
        bg_colours = set()
        if sorted_colours:
            bg_colours.add(sorted_colours[0][0])
            if len(sorted_colours) > 1 and sorted_colours[1][1] > 0.1 * total:
                bg_colours.add(sorted_colours[1][0])

        # Collect non-background cells
        non_bg = []
        for r in range(rows):
            for c in range(cols):
                col = grid[r][c]
                if col not in bg_colours:
                    non_bg.append((r, c, col))

        if not non_bg:
            return f"Grid {rows}x{cols}. No non-bg cells."

        # Group by colour and by row cluster (groups are separated by ~5 rows)
        colour_groups = defaultdict(lambda: defaultdict(list))  # colour -> group_id -> list of (r,c)
        for r, c, col in non_bg:
            group_id = (r - 2) // 5   # works for rows 0..16; 2..6->0, 7..11->1, 12..16->2
            if group_id < 0:
                group_id = 0
            elif group_id > 2:
                group_id = 2
            colour_groups[col][group_id].append((r, c))

        # Build summary parts
        parts = [f"Grid {rows}x{cols}."]
        for colour in sorted(colour_groups.keys()):
            groups = colour_groups[colour]
            group_strs = []
            for gid in sorted(groups.keys()):
                cells = groups[gid]
                # All cells in a group should share the same row (except possible edge cases)
                rows_set = set(r for r, _ in cells)
                if len(rows_set) == 1:
                    group_row = next(iter(rows_set))
                else:
                    # If multiple rows, take the smallest (should not happen)
                    group_row = min(rows_set)
                cols_list = sorted(c for _, c in cells)
                count = len(cells)
                wrap = 1 if group_row in {6, 11, 16} else 0
                group_strs.append(
                    f"G{gid}:r{group_row},c[{','.join(str(x) for x in cols_list)}],n{count},w{wrap}"
                )
            # Colour label – use abbreviated names to save space
            colour_abbr = colour if len(colour) <= 8 else colour[:8]
            parts.append(f"{colour_abbr}:{' '.join(group_strs)}")

        result = ' '.join(parts)
        if not result.strip():
            return "State unchanged."
        return result[:2000]  # Hard limit

    except Exception:
        return "State unknown."


def _parse_grid(obs: str):
    """
    Parse the observation string into a 2‑list of colour names (strings).
    Handles both Autumn‑style JSON and ARC integer grid formats.
    Returns None on failure.
    """
    # --- Try Autumn (JSON) format first ---
    if "[[" in obs:
        start = obs.find("[[")
        end = obs.rfind("]]") + 2
        if end > start:
            try:
                grid = json.loads(obs[start:end])
                if isinstance(grid, list) and len(grid) > 0 and isinstance(grid[0], list):
                    return [[str(cell) for cell in row] for row in grid]
            except Exception:
                pass

    # --- Fallback: ARC integer grid format ---
    palette = {
        0: "black", 1: "blue", 2: "red", 3: "green", 4: "yellow",
        5: "gray", 6: "magenta", 7: "orange", 8: "lightblue",
        9: "maroon", 10: "white", 11: "darkgray"
    }
    lines = obs.split("\n")
    grid_rows = []
    in_grid = False
    for line in lines:
        stripped = line.strip()
        if stripped.startswith("<grid"):
            in_grid = True
            continue
        if in_grid and stripped.startswith("[") and stripped.endswith("]"):
            inner = stripped[1:-1]
            parts = inner.split(",")
            row_ints = []
            for p in parts:
                p = p.strip()
                if p:
                    try:
                        val = int(p)
                        row_ints.append(val)
                    except ValueError:
                        pass
            if row_ints:
                colour_row = [palette.get(v, f"_{v}") for v in row_ints]
                grid_rows.append(colour_row)
        elif in_grid and stripped in ("", "========== Start of Direct Observation =========="):
            continue
    if grid_rows:
        return grid_rows
    return None
